"""بنك وضعيات التاريخ والجغرافيا — السنة الأولى إعدادية."""
B = {
"الدرس 1: مفهوم التاريخ ومراحله": [
 ("الخط الزمني", "ارسم خطًا زمنيًا وضع عليه الأحداث الآتية: ميلاد المسيح عليه السلام، الهجرة النبوية (622 م)، استقلال موريتانيا (1960 م)، فتح الأندلس (711 م).", "ميلاد المسيح (السنة 1) ← الهجرة (622) ← فتح الأندلس (711) ← الاستقلال (1960)، مع احترام سلّم منتظم على الخط."),
 ("التاريخ وأهميته", "سأل أحمد جده: «لماذا ندرس أحداثًا وقعت منذ قرون؟».\n1) عرّف التاريخ.\n2) اذكر فائدتين لدراسة التاريخ.\n3) ساعد الجد على إقناع أحمد بمثال من تاريخ بلدك.", "1) التاريخ هو العلم الذي يدرس ماضي الإنسان وأحداثه بالاعتماد على المصادر.\n2) فهم الحاضر، أخذ العبر، معرفة الهوية والانتماء.\n3) مثال: معرفة دور المرابطين في نشر الإسلام يعرّفنا بأصول هويتنا."),
 ("مراحل التاريخ", "رتّب المراحل الكبرى للتاريخ ترتيبًا زمنيًا: العصر الحديث، ما قبل التاريخ، العصر الوسيط، العصر القديم، العصر المعاصر.\nثم حدد الحدث الذي يفصل بين ما قبل التاريخ والتاريخ.", "ما قبل التاريخ ← العصر القديم ← العصر الوسيط ← العصر الحديث ← العصر المعاصر.\nالحدث الفاصل: اختراع الكتابة (حوالي 3200 ق.م)."),
 ("مصادر التاريخ", "عثر تلاميذ في رحلة مدرسية على قطعة فخار قديمة ورسوم على صخرة، وقرأوا مخطوطًا في مكتبة بشنقيط.\n1) صنّف هذه الأشياء إلى مصادر مادية ومصادر مكتوبة.\n2) أضف مصدرًا شفويًا.", "1) مادية: الفخار، الرسوم الصخرية ؛ مكتوبة: المخطوط.\n2) الروايات الشفوية (حكايات الشيوخ، الشعر الحساني)."),
 ("الحساب الزمني", "وقعت معركة سنة 1050 م، ووُلد عالم سنة 250 ق.م.\n1) كم سنة مضت على المعركة إلى سنة 2026؟\n2) في أي قرن وقعت المعركة؟\n3) ما الفرق بين التاريخ الهجري والتاريخ الميلادي؟", "1) 2026 − 1050 = 976 سنة.\n2) القرن الحادي عشر الميلادي.\n3) الهجري يبدأ بهجرة النبي ﷺ (622 م) ويعتمد الأشهر القمرية، والميلادي يبدأ بميلاد المسيح عليه السلام ويعتمد الأشهر الشمسية."),
],
"الدرس 1: مفهوم الجغرافيا وأنواعها": [
 ("الاتجاهات الأصلية", "وقف تلميذ في ساحة المدرسة صباحًا ووجهه نحو الشمس.\n1) ما الاتجاه الذي ينظر إليه؟\n2) حدد الاتجاهات الثلاثة الأخرى بالنسبة إليه.", "1) الشرق (مشرق الشمس).\n2) خلفه الغرب، عن يساره الشمال، عن يمينه الجنوب."),
 ("الجغرافيا وفروعها", "1) عرّف الجغرافيا.\n2) اذكر فرعين من فروعها مع مثال لموضوع يدرسه كل فرع.", "1) علم يدرس سطح الأرض والظواهر الطبيعية والبشرية وتوزيعها.\n2) الجغرافيا الطبيعية (التضاريس، المناخ) ؛ الجغرافيا البشرية (السكان، المدن، الأنشطة الاقتصادية)."),
 ("طبيعية أم بشرية؟", "صنّف المواضيع الآتية إلى جغرافيا طبيعية وجغرافيا بشرية: الكثبان الرملية ؛ الهجرة نحو نواكشوط ؛ نهر السنغال ؛ الصيد البحري ؛ الأمطار ؛ الطرق.", "طبيعية: الكثبان الرملية، نهر السنغال، الأمطار.\nبشرية: الهجرة نحو نواكشوط، الصيد البحري، الطرق."),
 ("أدوات الجغرافي", "يريد تلميذ دراسة توزيع السكان في ولايته.\n1) اذكر ثلاث أدوات يستعين بها.\n2) ما فائدة الخريطة بالنسبة إليه؟", "1) الخريطة، الإحصائيات، الصور، المبيانات، البوصلة.\n2) تمكّنه من تحديد أماكن تركّز السكان وتوزيعهم."),
 ("مقياس الخريطة", "على خريطة مقياسها 1/1 000 000، المسافة بين نواكشوط وروصو 20 سم.\n1) ما المسافة الحقيقية بالكيلومتر؟\n2) ماذا يعني المقياس؟", "1) 20 × 1 000 000 = 20 000 000 سم = 200 كلم.\n2) كل 1 سم على الخريطة يساوي 1 000 000 سم (10 كلم) في الواقع."),
],
"الدرس 2: الحضارات القديمة": [
 ("الكتابة", "1) لماذا يُعدّ اختراع الكتابة حدثًا عظيمًا؟\n2) اذكر نوعين من الكتابة القديمة.", "1) لأنه سمح بتدوين المعارف والقوانين والأحداث ونقلها، وبه يبدأ التاريخ.\n2) الهيروغليفية (مصر)، المسمارية (بلاد الرافدين)."),
 ("حضارة وادي النيل", "1) أين قامت الحضارة المصرية القديمة؟\n2) اذكر مظهرين من مظاهرها.\n3) ما علاقة النيل بقيام هذه الحضارة؟", "1) في وادي النيل بمصر.\n2) الأهرامات، الكتابة الهيروغليفية، الزراعة المنظمة.\n3) وفّر الماء والطمي الخصب فقامت الزراعة والاستقرار."),
 ("حضارة بلاد الرافدين", "1) بين أي نهرين قامت حضارة بلاد الرافدين؟\n2) اذكر إنجازين لها.", "1) بين دجلة والفرات.\n2) الكتابة المسمارية، قانون حمورابي، الري."),
 ("الحضارات والأنهار", "لاحظ أن أغلب الحضارات القديمة قامت قرب الأنهار.\nفسّر هذه الملاحظة بثلاثة أسباب.", "توفر الماء للشرب والزراعة، خصوبة التربة، سهولة التنقل والتجارة عبر النهر."),
 ("تراث الحضارات", "اذكر اختراعين من الحضارات القديمة ما زلنا نستفيد منهما اليوم.", "الكتابة، التقويم، العجلة، الري، النظام العشري."),
],
"الدرس 2: شكل الأرض، أبعادها وحركتها": [
 ("الفصول الأربعة", "لماذا يكون الطقس حارًا في موريتانيا في يونيو وأقل حرارة في يناير؟", "بسبب ميل محور الأرض ودورانها حول الشمس: في يونيو تكون أشعة الشمس أقرب إلى العمودية على نصف الكرة الشمالي فترتفع الحرارة، وفي يناير تكون مائلة."),
 ("حركة الأرض حول نفسها", "تساءلت فاطمة: لماذا يتعاقب الليل والنهار؟\n1) ما الحركة المسؤولة عن ذلك؟\n2) كم تستغرق؟\n3) في أي اتجاه تدور الأرض؟", "1) دوران الأرض حول نفسها (الحركة اليومية).\n2) 24 ساعة تقريبًا.\n3) من الغرب إلى الشرق."),
 ("حركة الأرض حول الشمس", "1) كم تستغرق دورة الأرض حول الشمس؟\n2) ما النتيجة الأساسية لهذه الحركة؟\n3) لماذا تكون السنة الكبيسة 366 يومًا؟", "1) 365 يومًا وربع اليوم تقريبًا.\n2) تعاقب الفصول الأربعة.\n3) لأن الربع يوم يتجمع كل أربع سنوات فيضاف يوم."),
 ("شكل الأرض وأبعادها", "1) ما شكل الأرض؟\n2) اذكر دليلين على كروية الأرض.\n3) كم يبلغ محيطها عند خط الاستواء تقريبًا؟", "1) شبه كروية (مفلطحة عند القطبين).\n2) صور الأقمار الاصطناعية، ظهور السفينة تدريجيًا في الأفق، ظل الأرض الدائري على القمر.\n3) حوالي 40 000 كلم."),
 ("خطوط الطول والعرض", "1) ما الخط الأساسي لخطوط العرض؟ وما الخط الأساسي لخطوط الطول؟\n2) في أي نصف من الكرة الأرضية تقع موريتانيا؟", "1) خط الاستواء ؛ خط غرينتش.\n2) في النصف الشمالي والنصف الغربي."),
],
"الدرس 3: تاريخ موريتانيا القديم": [
 ("موريتانيا قبل التاريخ", "1) ما الدليل على أن الصحراء الموريتانية كانت خضراء قديمًا؟\n2) اذكر موقعًا أثريًا قديمًا في موريتانيا.", "1) الرسوم الصخرية لحيوانات كالفيلة والزرافات، والأدوات الحجرية.\n2) مواقع ظهر تيشيت، الرسوم الصخرية بآدرار."),
 ("ظهر تيشيت وولاتة", "1) بماذا تشتهر منطقة ظهر تيشيت؟\n2) لماذا تُعدّ مدن تيشيت وولاتة ووادان وشنقيط تراثًا عالميًا؟", "1) بقرى حجرية قديمة تدل على استقرار زراعي ورعوي مبكر.\n2) لأنها مدن تاريخية قديمة (قصور) كانت مراكز للتجارة والعلم ومسجلة لدى اليونسكو."),
 ("التجارة الصحراوية", "1) ما الحيوان الذي سهّل التجارة عبر الصحراء؟\n2) اذكر سلعتين كانتا تُنقلان عبرها.", "1) الجمل.\n2) الملح، الذهب، التمور، الأقمشة."),
 ("مملكة غانا", "1) أين قامت مملكة غانا؟\n2) ما اسم عاصمتها الواقعة اليوم في موريتانيا؟", "1) في غرب إفريقيا (جنوب شرق موريتانيا وغرب مالي).\n2) كومبي صالح."),
],
"الدرس 3: أشكال التضاريس الرئيسية": [
 ("أشكال التضاريس", "عرّف كلا من: الجبل، الهضبة، السهل، الوادي.", "الجبل: مرتفع شديد الانحدار ؛ الهضبة: أرض مرتفعة مستوية السطح ؛ السهل: أرض منخفضة مستوية ؛ الوادي: منخفض طولي يجري فيه الماء أو جرى فيه."),
 ("تضاريس موريتانيا", "1) اذكر هضبة وسهلًا في موريتانيا.\n2) ما أعلى قمة في موريتانيا؟", "1) هضبة آدرار (أو تكانت) ؛ سهل شمامة على ضفة نهر السنغال.\n2) كدية الجل قرب ازويرات."),
 ("التضاريس والإنسان", "لماذا يتركز السكان والمزارعون على ضفة نهر السنغال أكثر من الهضاب؟", "لتوفر الماء وخصوبة الأرض وانبساطها مما يسهل الزراعة والاستقرار."),
 ("الكثبان الرملية", "1) كيف تتكون الكثبان الرملية؟\n2) ما خطرها على المدن والطرق؟", "1) بتجميع الرياح للرمال.\n2) زحفها يغطي الطرق والمنازل والمزارع (مثال: نواكشوط، طريق الأمل)."),
],
"الدرس 4: شبه الجزيرة العربية قبل الإسلام": [
 ("الموقع والحياة", "1) حدّد موقع شبه الجزيرة العربية.\n2) صف الحياة الاقتصادية فيها قبل الإسلام.", "1) في جنوب غرب آسيا، بين البحر الأحمر والخليج العربي وبحر العرب.\n2) الرعي في البادية، التجارة (رحلتا الشتاء والصيف)، الزراعة في اليمن والواحات."),
 ("مكة قبل الإسلام", "1) لماذا كانت لمكة مكانة خاصة؟\n2) ما القبيلة التي كانت تسكنها؟", "1) لوجود الكعبة وكونها مركزًا تجاريًا.\n2) قريش."),
 ("الحياة الاجتماعية", "اذكر صفتين حميدتين وصفتين ذميمتين عند العرب قبل الإسلام.", "حميدة: الكرم، الشجاعة، الوفاء ؛ ذميمة: وأد البنات، الثأر، عبادة الأصنام."),
 ("الأسواق", "اذكر سوقًا من أسواق العرب قبل الإسلام ودوره.", "سوق عكاظ: للتجارة وإلقاء الشعر والتفاخر."),
],
"الدرس 4: الغلاف الجوي": [
 ("الغلاف الجوي", "1) عرّف الغلاف الجوي.\n2) اذكر غازين من مكوناته ونسبتهما.\n3) ما أهميته للحياة؟", "1) غلاف غازي يحيط بالأرض.\n2) الآزوت حوالي 78 %، الأكسجين حوالي 21 %.\n3) يوفر الهواء للتنفس، يحمي من الأشعة الضارة والنيازك، ويعدّل الحرارة."),
 ("طبقات الغلاف الجوي", "رتب طبقات الغلاف الجوي من الأرض إلى الأعلى، وحدد الطبقة التي تحدث فيها الظواهر الجوية.", "التروبوسفير ← الستراتوسفير ← الميزوسفير ← الترموسفير. الظواهر الجوية في التروبوسفير."),
 ("طبقة الأوزون", "1) في أي طبقة توجد طبقة الأوزون؟\n2) ما دورها؟\n3) كيف نحافظ عليها؟", "1) في الستراتوسفير.\n2) تحمي من الأشعة فوق البنفسجية الضارة.\n3) الحد من الغازات الضارة كالمبيدات وغازات التبريد القديمة."),
 ("تلوث الهواء", "لاحظ أحمد دخانًا كثيفًا من حرق النفايات قرب مدرسته.\n1) ما أثر ذلك على الغلاف الجوي وعلى صحة التلاميذ؟\n2) اقترح حلين.", "1) تلوث الهواء وأمراض الجهاز التنفسي.\n2) جمع النفايات في أماكنها، منع الحرق، التشجير."),
],
"الدرس 5: ظهور الإسلام": [
 ("البعثة النبوية", "1) متى وأين بُعث النبي محمد ﷺ؟\n2) ما مراحل الدعوة في مكة؟", "1) سنة 610 م تقريبًا في مكة المكرمة (غار حراء).\n2) الدعوة السرية ثم الدعوة الجهرية."),
 ("موقف قريش", "1) كيف واجهت قريش الدعوة الإسلامية؟\n2) لماذا هاجر بعض المسلمين إلى الحبشة؟", "1) بالسخرية والتعذيب والمقاطعة.\n2) فرارًا من أذى قريش، لأن ملكها كان عادلًا."),
 ("الهجرة النبوية", "1) في أي سنة كانت الهجرة إلى المدينة؟\n2) ما أهميتها في التاريخ الإسلامي؟", "1) سنة 622 م (1 هـ).\n2) بداية قيام الدولة الإسلامية، واعتمدت بداية للتقويم الهجري."),
],
"الدرس 5: المناخ والعوامل المؤثرة فيه": [
 ("الطقس والمناخ", "قال المذيع: «الجو اليوم حار في نواكشوط». وقال الأستاذ: «مناخ موريتانيا صحراوي في أغلبه».\nما الفرق بين الطقس والمناخ؟", "الطقس: حالة الجو في مكان ما خلال مدة قصيرة ؛ المناخ: معدل حالات الجو لمدة طويلة (30 سنة)."),
 ("عوامل المناخ", "اذكر أربعة عوامل تؤثر في المناخ.", "الموقع بالنسبة لخط الاستواء (دائرة العرض)، القرب أو البعد عن البحر، الارتفاع، التيارات البحرية، الرياح."),
 ("أثر البحر", "لماذا تكون الحرارة في نواكشوط ونواذيبو أقل منها في النعمة صيفًا؟", "بسبب تأثير المحيط الأطلسي الملطّف (والتيار البحري البارد)، بينما النعمة داخلية بعيدة عن البحر."),
],
"الدرس 6: قيام الدولة الإسلامية": [
 ("أسس الدولة في المدينة", "اذكر ثلاثة أعمال قام بها النبي ﷺ لتأسيس الدولة في المدينة.", "بناء المسجد، المؤاخاة بين المهاجرين والأنصار، كتابة الصحيفة (الوثيقة) مع سكان المدينة."),
 ("الغزوات", "رتب زمنيًا: فتح مكة، غزوة بدر، غزوة أحد، غزوة الخندق.", "بدر (2 هـ) ← أحد (3 هـ) ← الخندق (5 هـ) ← فتح مكة (8 هـ)."),
 ("فتح مكة", "1) في أي سنة فُتحت مكة؟\n2) كيف تعامل النبي ﷺ مع أهلها؟", "1) سنة 8 هـ (630 م).\n2) عفا عنهم وقال: «اذهبوا فأنتم الطلقاء»."),
],
"الدرس 6: عناصر المناخ": [
 ("عناصر المناخ", "اذكر عناصر المناخ وأداة قياس كل عنصر.", "الحرارة: المحرار ؛ الأمطار: المطراس ؛ الضغط الجوي: البارومتر ؛ الرياح: دوارة الرياح والأنيمومتر ؛ الرطوبة: الهيغرومتر."),
 ("حساب المعدل الحراري", "سُجلت درجات الحرارة القصوى خلال أسبوع في كيفة: 38، 40، 41، 39، 42، 40، 40 درجة.\nاحسب معدل الحرارة الأسبوعي والمدى الحراري.", "المعدل = 280 ÷ 7 = 40 درجة ؛ المدى = 42 − 38 = 4 درجات."),
 ("التساقطات", "سجل مطراس في سيلبابي 600 ملم في السنة، وفي نواكشوط 100 ملم.\n1) كم مرة تفوق أمطار سيلبابي أمطار نواكشوط؟\n2) فسّر هذا الفرق.", "1) 600 ÷ 100 = 6 مرات.\n2) سيلبابي في الجنوب أقرب إلى المناطق المدارية الرطبة، ونواكشوط في المجال الصحراوي."),
],
"الدرس 7: الخلافة الراشدية (خلافة أبي بكر وعمر)": [
 ("خلافة أبي بكر", "1) كيف تمت بيعة أبي بكر الصديق؟\n2) اذكر عملين بارزين في خلافته.", "1) بالشورى في سقيفة بني ساعدة ثم البيعة العامة.\n2) حروب الردة، جمع القرآن الكريم، بدء الفتوحات."),
 ("خلافة عمر بن الخطاب", "اذكر ثلاثة من إنجازات عمر بن الخطاب رضي الله عنه.", "اتساع الفتوحات (الشام، العراق، مصر)، تنظيم الدواوين، وضع التقويم الهجري، تأسيس المدن (الكوفة، البصرة)."),
 ("العدل في الحكم", "اشتهر عمر بالعدل. اقترح موقفًا من حياتك المدرسية تطبق فيه قيمة العدل.", "مثال: توزيع المهام بالتساوي بين أفراد الفريق، الإنصاف عند التحكيم في المباراة."),
],
"الدرس 7: المناطق المناخية الكبرى": [
 ("المناطق المناخية", "اذكر المناطق المناخية الكبرى في العالم ومميزات المنطقة الحارة.", "الحارة، المعتدلة، الباردة ؛ الحارة: حرارة مرتفعة طول السنة، وتشمل المناخ الاستوائي والمداري والصحراوي."),
 ("مناخ موريتانيا", "1) ما المناخان السائدان في موريتانيا؟\n2) حدد مجال كل منهما.", "1) المناخ الصحراوي والمناخ الساحلي (شبه الجاف).\n2) الصحراوي في الشمال والوسط، والساحلي في الجنوب."),
 ("المناخ والنبات", "لماذا تنتشر غابات كثيفة في المنطقة الاستوائية بينما يقل النبات في الصحراء؟", "لأن المنطقة الاستوائية حارة ورطبة طول السنة، أما الصحراء فأمطارها قليلة جدًا."),
],
"الدرس 8: الخلافة الراشدية (خلافة عثمان وعلي)": [
 ("خلافة عثمان", "اذكر عملين بارزين في خلافة عثمان بن عفان رضي الله عنه.", "نسخ المصحف وتوحيده، إنشاء أول أسطول بحري إسلامي، توسيع المسجد النبوي."),
 ("خلافة علي", "1) ما الظروف التي تولى فيها علي بن أبي طالب الخلافة؟\n2) بماذا انتهت الخلافة الراشدية؟", "1) بعد مقتل عثمان، في ظروف فتنة واضطراب.\n2) باستشهاد علي سنة 40 هـ وقيام الدولة الأموية."),
 ("الخلفاء الراشدون", "رتب الخلفاء الراشدين ترتيبًا زمنيًا واذكر لقبًا لكل منهم.", "أبو بكر (الصديق) ← عمر (الفاروق) ← عثمان (ذو النورين) ← علي (أبو الحسن، كرّم الله وجهه)."),
],
"الدرس 8: المياه السطحية والجوفية": [
 ("مصادر المياه", "صنّف: نهر السنغال، بحيرة ألاك، الآبار، الفرشة المائية لإديني، المطر.\nإلى مياه سطحية ومياه جوفية.", "سطحية: نهر السنغال، بحيرة ألاك ؛ جوفية: الآبار، فرشة إديني. (المطر مصدر للنوعين)."),
 ("تزويد نواكشوط بالماء", "1) من أين تحصل نواكشوط على مياه الشرب؟\n2) لماذا يجب ترشيد استهلاك الماء؟", "1) من مشروع آفطوط الساحلي (نهر السنغال) ومن فرشة إديني الجوفية.\n2) لأن الماء مورد نادر في بلد صحراوي والطلب عليه يتزايد."),
 ("ترشيد الماء", "تسرب الماء من صنبور في المدرسة: 10 لترات في الساعة.\n1) كم لترًا يضيع في يوم؟ في أسبوع؟\n2) اقترح سلوكين لترشيد الماء.", "1) 10 × 24 = 240 لترًا في اليوم ؛ 240 × 7 = 1 680 لترًا في الأسبوع.\n2) إصلاح الصنابير، إغلاقها بعد الاستعمال، إعادة استعمال ماء الغسيل للري."),
],
"الدرس 9: التصحر وحماية البيئة": [
 ("التصحر", "1) عرّف التصحر.\n2) اذكر سببين طبيعيين وسببين بشريين.", "1) تدهور الأراضي وتحولها إلى أراض صحراوية.\n2) طبيعية: الجفاف، الرياح ؛ بشرية: قطع الأشجار، الرعي الجائر."),
 ("مكافحة التصحر", "اقترح ثلاثة حلول لمكافحة التصحر في موريتانيا.", "التشجير (الحزام الأخضر حول نواكشوط)، تثبيت الكثبان، تنظيم الرعي، استعمال الغاز بدل الحطب."),
 ("الحطب والفحم", "تستهلك أسرة 3 أكياس فحم في الشهر، وكل كيس يتطلب قطع شجرتين.\n1) كم شجرة تُقطع في السنة؟\n2) ما البديل؟", "1) 3 × 2 × 12 = 72 شجرة.\n2) استعمال غاز البوتان أو الطاقة الشمسية."),
],
"الدرس 9: الدولة الأموية": [
 ("قيام الدولة الأموية", "1) من مؤسس الدولة الأموية؟ وما عاصمتها؟\n2) في أي سنة قامت؟", "1) معاوية بن أبي سفيان ؛ دمشق.\n2) سنة 41 هـ (661 م)."),
 ("إنجازات الأمويين", "اذكر ثلاثة إنجازات للدولة الأموية.", "تعريب الدواوين، سك النقود العربية، الفتوحات (المغرب والأندلس)، بناء قبة الصخرة والمسجد الأموي."),
 ("الفتوحات في المغرب", "1) من القائد الذي أسس القيروان؟\n2) من فتح الأندلس؟", "1) عقبة بن نافع.\n2) طارق بن زياد وموسى بن نصير."),
],
"الدرس 10: السكان: البنية والتوزيع الجغرافي": [
 ("توزيع السكان", "1) لماذا يتركز سكان موريتانيا في الجنوب والمدن الكبرى؟\n2) اذكر ولاية مكتظة وأخرى قليلة السكان.", "1) لتوفر الماء والأراضي الزراعية في الجنوب، والخدمات والعمل في المدن.\n2) مكتظة: نواكشوط ؛ قليلة: تيرس زمور أو إينشيري."),
 ("الكثافة السكانية", "مساحة ولاية 25 000 كلم²، وعدد سكانها 500 000 نسمة.\nاحسب الكثافة السكانية.", "500 000 ÷ 25 000 = 20 نسمة/كلم²."),
 ("الهرم السكاني", "يكون قاعدة الهرم السكاني لموريتانيا عريضة وقمته ضيقة.\nماذا تستنتج عن تركيبة السكان؟", "المجتمع فتي: نسبة الأطفال والشباب مرتفعة ونسبة المسنين ضعيفة."),
],
"الدرس 10: الدولة العباسية": [
 ("قيام الدولة العباسية", "1) متى قامت الدولة العباسية؟\n2) ما عاصمتها ومن بناها؟", "1) سنة 132 هـ (750 م).\n2) بغداد، بناها أبو جعفر المنصور."),
 ("الحضارة العباسية", "اذكر مظهرين من مظاهر ازدهار الحضارة في العصر العباسي.", "بيت الحكمة والترجمة، ازدهار العلوم (الطب، الرياضيات، الفلك)، ازدهار التجارة والعمران."),
 ("العلماء", "اذكر عالمين من العصر العباسي ومجال كل منهما.", "الخوارزمي: الرياضيات (الجبر) ؛ ابن سينا أو الرازي: الطب."),
],
"الدرس 11: السكان: النمو والهجرة": [
 ("النمو الطبيعي", "في بلد ما: نسبة الولادات 35 ‰ ونسبة الوفيات 8 ‰.\nاحسب نسبة النمو الطبيعي، وما نتائج النمو السريع؟", "35 − 8 = 27 ‰ (2,7 %). النتائج: ضغط على المدارس والصحة والسكن والعمل."),
 ("الهجرة الداخلية", "1) لماذا يهاجر سكان الأرياف إلى نواكشوط؟\n2) اذكر نتيجتين لهذه الهجرة.", "1) البحث عن العمل والتعليم والخدمات، وبسبب الجفاف.\n2) توسع الأحياء العشوائية، ضغط على المرافق، تراجع الأنشطة الريفية."),
 ("أنواع الهجرة", "ميّز بين الهجرة الداخلية والهجرة الخارجية مع مثال لكل منهما.", "داخلية: داخل البلد (من الريف إلى المدينة) ؛ خارجية: إلى بلد آخر (الهجرة إلى أوروبا أو دول الجوار)."),
],
"الدرس 11: الدولة الأموية في الأندلس": [
 ("قيام الدولة الأموية في الأندلس", "1) من مؤسسها؟ وما عاصمتها؟\n2) في أي سنة؟", "1) عبد الرحمن الداخل (صقر قريش) ؛ قرطبة.\n2) سنة 138 هـ (756 م)."),
 ("حضارة الأندلس", "اذكر معلمين من معالم الحضارة الإسلامية في الأندلس.", "مسجد قرطبة، قصر الحمراء بغرناطة، مدينة الزهراء."),
 ("أثر الأندلس في أوروبا", "كيف ساهمت الأندلس في نهضة أوروبا؟", "بنقل العلوم والكتب المترجمة ووجود الجامعات التي درس فيها الأوروبيون."),
],
"الدرس 12: المدن: النشأة، الأنواع والبنية الحضرية": [
 ("نشأة المدن", "اذكر ثلاثة عوامل ساهمت في نشأة المدن الموريتانية.", "التجارة (شنقيط، ولاتة)، الإدارة (نواكشوط عاصمة)، المعادن (ازويرات)، الصيد (نواذيبو)."),
 ("أنواع المدن", "صنف المدن حسب وظيفتها: ازويرات، نواذيبو، نواكشوط، شنقيط.", "ازويرات: منجمية ؛ نواذيبو: صناعية ومينائية (صيد) ؛ نواكشوط: إدارية وسياسية ؛ شنقيط: تاريخية وثقافية."),
 ("نمو نواكشوط", "كان عدد سكان نواكشوط حوالي 5 000 نسمة سنة 1960، وأصبح يتجاوز المليون.\nاذكر سببين لهذا النمو ومشكلتين ناتجتين عنه.", "الأسباب: الهجرة الريفية، كونها العاصمة والمركز الاقتصادي.\nالمشاكل: الأحياء العشوائية (الكزرات)، نقص الماء والصرف الصحي، الازدحام."),
],
"الدرس 12: الدولة الفاطمية": [
 ("الدولة الفاطمية", "1) أين قامت الدولة الفاطمية أولًا؟\n2) ما المدينة التي أسستها في مصر؟", "1) في إفريقية (تونس) سنة 297 هـ.\n2) القاهرة، والجامع الأزهر."),
 ("الأزهر", "1) متى أُسس الجامع الأزهر ومن أسسه؟\n2) ما دوره اليوم؟", "1) سنة 361 هـ تقريبًا في عهد الفاطميين.\n2) جامعة إسلامية كبرى للتعليم والعلم."),
],
"الدرس 13: المدن: المخططات، الوظائف والمشاكل": [
 ("مشاكل المدن", "اذكر أربع مشاكل تعاني منها المدن الكبرى في موريتانيا واقترح حلًا لكل منها.", "الازدحام: تطوير النقل العمومي ؛ النفايات: الجمع المنتظم والتدوير ؛ السكن العشوائي: التخطيط العمراني ؛ نقص الماء: توسيع الشبكات."),
 ("مخطط المدينة", "ميّز بين المخطط الشبكي (المتعامد) والمخطط العشوائي للمدينة.", "الشبكي: شوارع مستقيمة متعامدة منظمة ؛ العشوائي: أزقة ملتوية غير منظمة كما في الأحياء القديمة."),
],
"الدرس 13: الدولة العثمانية": [
 ("الدولة العثمانية", "1) من مؤسس الدولة العثمانية؟\n2) من فتح القسطنطينية وفي أي سنة؟", "1) عثمان الأول.\n2) محمد الفاتح سنة 1453 م."),
 ("امتداد الدولة العثمانية", "اذكر ثلاث مناطق خضعت للدولة العثمانية.", "الأناضول، البلقان، الشام، مصر، شمال إفريقيا (الجزائر، تونس، ليبيا)."),
],
}
